),

awards_transformed AS (
    SELECT
        abs(xxhash64(CONCAT(f.funder_id, ':', LOWER(g.project_code)))) % 9000000000 as id,

        COALESCE(NULLIF(TRIM(g.title_en), ''), g.title_cs, g.title) as display_name,

