        CAST(NULL AS STRING) as currency,  -- §6.7 waiver

        struct(
            CONCAT('https://openalex.org/F', f.funder_id) as id,
            f.display_name,
            f.ror_id,
            f.doi
        ) as funder,

        CASE
            WHEN LOWER(COALESCE(g.grant_type, '')) RLIKE 'fellowship|scholarship|postdoc|dissertation|traineeship' THEN 'fellowship'
